#pragma once
#include "kstationVoiceAllocationTask.h"
#include <optional>
namespace kstation {
class ControllerVoiceActivationTask final {
 using T=VoiceActivationTask;using S=T::Stage;using V=VoiceAddressTask;using P=VoicePartAddressTask;using C=VoicePartCopyTask;using Q=VoiceVelocityTask;using D=VoiceDspSelectTask;using E=VoiceDspReadTask;
public:
 using Child=T::Child;explicit ControllerVoiceActivationTask(uint32_t patch):task_(patch){}bool complete()const{return task_.complete();}bool awaitingDsp()const{return (dspSelect_&&dspSelect_->awaitingDsp())||(dspRead_&&dspRead_->awaitingDsp());}uint16_t dspAddress()const{return dspRead_?dspRead_->command():0;}Child child()const{return task_.child();}uint32_t voice()const{return task_.voice();}uint8_t part()const{return task_.part();}bool resumeDsp(Child c,uint16_t command=0){if(!awaitingDsp()||c!=task_.child())return false;(void)command;return dspSelect_?dspSelect_->resumeDsp():dspRead_->resumeDsp();}
 bool stackWrites()const{if(dspSelect_)return dspSelect_->stage()==D::Stage::DispatchInvalidate;if(dspRead_)return dspRead_->stage()==E::Stage::DispatchRead;if(voice_||part_||copy_||velocity_)return false;auto s=task_.stage();return s==S::DispatchVoice||s==S::DispatchPart||s==S::DispatchVelocity||s==S::DispatchCopy||s==S::DispatchSelectDsp||s==S::DispatchWriteDsp;}
 unsigned nextClocks(int previous=-1)const{if(dspSelect_){D::Credits c{3,3,dspSelect_->stage()==D::Stage::Return?7u:10u};return dspSelect_->nextClocks(c);}if(dspRead_){E::Credits c{3,dspRead_->stage()==E::Stage::Return?7u:10u};return dspRead_->nextClocks(c);}if(voice_){V::Credits c{3,7};return voice_->nextClocks(c);}if(part_){P::Credits c{3,7};return part_->nextClocks(c);}if(copy_){C::Credits c{bus(copy_->source(),1,-1),bus(copy_->destination(),1,previous),7};return copy_->nextClocks(c);}if(velocity_){Q::Credits c{bus(velocity_->tableAddress(),1,-1),7};return velocity_->nextClocks(c);}uint32_t ra=0,wa=0;unsigned rn=0,wn=0;access(ra,rn,wa,wn);T::Credits c{rn?bus(ra,rn,-1):0,wn?bus(wa,wn,previous):0,task_.stage()==S::Return?7u:task_.stage()==S::DispatchVelocity?5u:10u};return task_.nextClocks(c);}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(dspSelect_){D::Credits c{3,3,dspSelect_->stage()==D::Stage::Return?7u:10u};auto used=dspSelect_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);},[&](D::Write f,uint16_t v){write(f==D::Write::First?0xd024:0xd026,v,2,cost);});if(dspSelect_->complete()){dspSelect_.reset();task_.resumeChild();}return used;}if(dspRead_){E::Credits c{3,dspRead_->stage()==E::Stage::Return?7u:10u};auto used=dspRead_->advanceBefore(cost,c,[&](){return read(0xd026,2,cost);});if(dspRead_->complete()){auto command=dspRead_->command();dspRead_.reset();task_.resumeChild(command);}return used;}if(voice_){V::Credits c{3,7};auto used=voice_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);});if(voice_->complete()){auto v=voice_->address();voice_.reset();task_.resumeChild(v);}return used;}if(part_){P::Credits c{3,7};auto used=part_->advanceBefore(cost,c,[&](){return read(0xd028,1,cost);});if(part_->complete()){auto v=part_->address();part_.reset();task_.resumeChild(v);}return used;}if(copy_){C::Credits c{bus(copy_->source(),1,-1),bus(copy_->destination(),1,previous),7};auto used=copy_->advanceBefore(cost,c,[&](){return read(copy_->source(),1,cost-2);},[&](uint8_t v){write(copy_->destination(),v,1,cost);});if(copy_->complete()){copy_.reset();task_.resumeChild();}return used;}if(velocity_){Q::Credits c{bus(velocity_->tableAddress(),1,-1),7};auto used=velocity_->advanceBefore(cost,c,[&](){return read(velocity_->tableAddress(),1,cost);});if(velocity_->complete()){auto v=velocity_->result();velocity_.reset();task_.resumeChild(v);}return used;}uint32_t ra=0,wa=0;unsigned rn=0,wn=0;access(ra,rn,wa,wn);T::Credits c{rn?bus(ra,rn,-1):0,wn?bus(wa,wn,previous):0,task_.stage()==S::Return?7u:task_.stage()==S::DispatchVelocity?5u:10u};auto used=task_.advanceBefore(cost,c,[&](T::Read){return read(ra&0xffffff,rn,cost);},[&](T::Write,uint32_t v){write(wa&0xffffff,v,wn,cost);});switch(task_.child()){case Child::Voice:voice_.emplace();break;case Child::Part:part_.emplace();break;case Child::Velocity:velocity_.emplace(task_.velocity(),task_.exponent(),task_.curve());break;case Child::Copy:copy_.emplace(task_.part());break;case Child::SelectDsp:dspSelect_.emplace();break;case Child::WriteDsp:dspRead_.emplace(0x805f);break;default:break;}return used;}
private:
 static unsigned bus(uint32_t a,unsigned n,int previous){unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((previous&1)||x!=uint32_t(previous|1))c+=x<0x400000?3:1;previous=int(x);}else{c+=x>=0xffffa0?1:3;previous=-1;}}return c;}
 void access(uint32_t&ra,unsigned&rn,uint32_t&wa,unsigned&wn)const{switch(task_.stage()){
 case S::ReadNote:ra=0xd02a;rn=1;break;case S::ReadTranspose:ra=task_.partAddress()+10;rn=1;break;case S::ReadUnit:ra=task_.partAddress()+15;rn=1;break;case S::ReadVelocity:ra=0xd02b;rn=1;break;case S::ReadCurve:ra=task_.partAddress()+13;rn=1;break;case S::ReadExponent:ra=task_.patch()+0xc3;rn=1;break;case S::ReadPart:ra=0xd028;rn=1;break;case S::ReadActualNote:ra=task_.voice()+13;rn=1;break;
 case S::WritePatch:wa=task_.voice();wn=4;break;case S::WriteNote:wa=task_.voice()+5;wn=1;break;case S::WriteTransposed:wa=task_.voice()+13;wn=1;break;case S::WriteHeld:wa=task_.partAddress()+14;wn=1;break;case S::WriteUnit:wa=task_.voice()+12;wn=1;break;case S::WriteVelocity:wa=task_.voice()+6;wn=1;break;case S::WriteAge:wa=task_.voice()+8;wn=4;break;case S::WritePart:wa=task_.voice()+4;wn=1;break;case S::WriteDelta:wa=task_.voice()+7;wn=1;break;case S::WriteFlag:wa=task_.voice()+17;wn=1;break;default:break;}}
 T task_;std::optional<V>voice_{};std::optional<P>part_{};std::optional<C>copy_{};std::optional<Q>velocity_{};std::optional<D>dspSelect_{};std::optional<E>dspRead_{};
};
}
